import heapq
import math

class Solution:
    def pickGifts(self, gifts: list[int], k: int) -> int:
        heap = [-g for g in gifts]
        heapq.heapify(heap)
        for _ in range(k):
            top = -heapq.heappop(heap)
            heapq.heappush(heap, -int(math.isqrt(top)))
        return -sum(heap)

